local _bA='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local _bM={}
for i=1,#_bA do _bM[string.sub(_bA,i,i)]=i-1 end

local function _b64(s)
    s=string.gsub(s,'[^'.._bA..'=]','')
    local out={}
    for i=1,#s,4 do
        local a=_bM[string.sub(s,i,i)] or 0
        local b=_bM[string.sub(s,i+1,i+1)] or 0
        local c=_bM[string.sub(s,i+2,i+2)] or 0
        local d=_bM[string.sub(s,i+3,i+3)] or 0
        local n=a*262144+b*4096+c*64+d
        local x=math.floor(n/65536)%256
        local y=math.floor(n/256)%256
        local z=n%256
        out[#out+1]=string.char(x)
        if string.sub(s,i+2,i+2)~='=' then out[#out+1]=string.char(y) end
        if string.sub(s,i+3,i+3)~='=' then out[#out+1]=string.char(z) end
    end
    return table.concat(out)
end

local function _bRun()
    local raw=_b64(table.concat(_bC))
    local out={}
    for i=1,#raw do
        local v=string.byte(raw,i)
        local k=_bK[((i-1)%#_bK)+1]
        out[i]=string.char((v-k-37)%256)
    end
    local source=table.concat(out)
    local fn,err=loadstring(source)
    if not fn then error('Beka Hub load error: '..tostring(err)) end
    return fn()
end

return _bRun()
